from edit import *

reel('P41',[
('“No início eu acompanhei mais…”','“No início eu acompanhei mais, agora eu acompanho menos. Ele faz o curso com total independência no momento.”','Áudio real da Flávia, mantendo duração e ritmo originais.'),
('Flávia, mãe do Fernando','A Flávia contou como o acompanhamento mudou na família dela. Vale observar quais partes seu filho já consegue fazer e onde ainda precisa de ajuda.','Helena apresenta a experiência sem prometer o mesmo resultado.'),
('Orientação para consultar.','Nas nossas aulas, ele pode pausar o vídeo, ouvir a instrução e conferir os critérios da etapa no botão Verificar esta parte.','Interface real com cada recurso mostrado no momento da fala.'),
('Acompanhe as tentativas.','Ao olhar o projeto, peça que mostre uma tentativa e a dúvida que ficou. Isso ajuda a escolher o próximo apoio.','Projeto aberto e conversa, sem simular novo depoimento.'),
('Siga @criecomhelenaejulio','Siga a gente para ouvir outras famílias e conhecer as atividades de criação.','Helena fecha.')])
cap('P41','“No início eu acompanhei mais, agora eu acompanho menos. Ele faz o curso com total independência no momento.” Flávia, mãe do Fernando.\n\nO relato mostra uma mudança percebida nessa família. Para acompanhar seu filho, observe quais passos ele já consegue seguir, que explicações consulta e onde ainda pede ajuda.\n\nNas nossas aulas, o vídeo pode ser pausado, a instrução pode ser ouvida e a verificação confere os critérios daquela parte. São referências para usar durante a construção.\n\nPeça que ele mostre algo que tentou e uma dúvida que ficou. A conversa ajuda a ajustar o apoio ao momento dele.\n\nSiga @criecomhelenaejulio para ouvir outras famílias contando suas experiências com a criação de jogos.')
note('P41','Mantém a fala real como abertura. Remove a atribuição de toda dependência à atividade e não promete que recursos da aula eliminarão os pedidos de ajuda.')

title('P42','“Terminei.” Falta combinar o que isso quer dizer.')
slide('P42',1,'“Terminei.”\n\nFalta combinar o que isso quer dizer.')
slide('P42',2,'A mochila está fechada, mas o estojo ficou na mesa.\n\nUma lista do que precisa entrar permite conferir antes de sair. A criança pode participar dessa checagem.')
slide('P42',3,'Saber o que fazer e saber como conferir são duas partes da tarefa.\n\nVale deixar os critérios visíveis e praticar a conferência junto com ele.')
slide('P42',4,'“Arrumar a mochila” pode vir com uma lista: caderno, estojo e garrafa.\n\nEle compara a lista com o que colocou. Você observa onde ainda precisa de apoio.')
slide('P42',5,'Ao criar um jogo, a condição de vitória também precisa ficar clara.\n\nNa Caça Estelar, do nosso Estúdio, o placar mostra quantas naves já foram derrotadas: 4 de 10.')
slide('P42',7,'Quem cria precisa dizer quando a partida termina e testar se o jogo reconhece esse momento.\n\nSiga @criecomhelenaejulio para ver como critérios viram regras que funcionam na tela.')
cap('P42','Fechar a mochila e conferir se os materiais entraram são ações diferentes. Uma lista ajuda a criança a participar das duas.\n\nEscolham uma tarefa e combinem como conferir o resultado. Ao terminar, peçam que compare com o combinado. O apoio pode continuar onde for necessário.\n\nCriar um jogo também exige definir o que conta como concluído. Na Caça Estelar, do nosso Estúdio, derrotar 10 naves leva à vitória. Perder os 3 escudos encerra a tentativa. Quem cria monta essas condições e testa os dois finais.\n\nO resultado esperado vira algo que dá para conferir.\n\nSiga @criecomhelenaejulio para descobrir como uma ideia ganha regras claras num jogo.')
note('P42','Preserva responsabilidade e conferência numa cena concreta. Não acusa o adulto de tomar a tarefa ao ajudar. O jogo exige construir e testar os critérios de encerramento.')

reel('P43',[
('“Foi legal.” E a conversa acabou.','“Foi legal.” E a conversa acabou. Você queria conhecer um pouco mais do que ele fez.','Helena ao lado da mesa; conversa encenada.'),
('“Me mostra uma parte.”','Experimente pedir: “me mostra uma parte que funcionou”. Vocês passam a conversar sobre algo que conseguem ver.','Criança escolhe um detalhe para demonstrar.'),
('Uma tecla pode revelar uma regra.','Neste parque do nosso Estúdio, apertar E num ponto faz surgir um tornado por doze segundos. Quem cria liga o lugar, a tecla e essa reação.','Mostrar ponto, tecla e tornado no Parque dos Brinquedos.'),
('O que você escolheu aqui?','No projeto do seu filho, pergunte o que ele escolheu naquela parte ou o que mudou depois de testar. A demonstração dá assunto.','Duas versões de uma regra, claramente identificadas como demonstração.'),
('Siga @criecomhelenaejulio','Siga a gente para conhecer as histórias e escolhas por trás de um jogo criado pela criança.','Helena encerra.')])
cap('P43','“Me mostra uma parte que funcionou” oferece um ponto concreto para a conversa.\n\nEle pode escolher o detalhe, testar e contar o que mudou. Se estiver cansado ou sem vontade de conversar, vocês podem combinar outro momento.\n\nNo Parque dos Brinquedos, exemplo do nosso Estúdio, apertar E no lugar indicado faz surgir um tornado por 12 segundos. Há um lugar, uma tecla e uma duração escolhidos por quem criou.\n\nNo projeto do seu filho, pergunte por uma escolha assim. Pode aparecer uma ideia, uma dificuldade ou uma descoberta que o “foi legal” não contou.\n\nSiga @criecomhelenaejulio para descobrir os assuntos que cabem dentro de um jogo.')
note('P43','Mantém o diálogo reconhecível e o pedido de demonstração. Não atribui toda resposta curta à pergunta do adulto nem promete medir aprendizagem em dez segundos.')

slide('P44',2,'Nessa batalha, a pergunta tem um motivo visível:\n\no monstrinho tem 20 de vida. Quantos golpes de 8 são necessários para vencer?')
slide('P44',3,'Uma forma de explorar uma conta é mostrar a decisão que ela ajuda a tomar.\n\nAo criar a batalha, seu filho pode escolher a força dos golpes e conferir o efeito.')
slide('P44',4,'Na Batalha de Monstrinhos, do nosso Estúdio, a Faísca de fogo tira 8 de vida do monstrinho de planta.\n\nO Jato de água tira 4. A escolha muda quantos golpes serão necessários.')
slide('P44',6,'Mudar a força do golpe muda a duração da luta.\n\nQuem cria calcula o resultado esperado, monta a regra e joga para conferir. A conta tem um efeito que aparece na tela.')
slide('P44',7,'Com golpes de 4, são cinco ataques para tirar 20 de vida. Com golpes de 8, são três.\n\nSiga @criecomhelenaejulio para descobrir as contas por trás das batalhas.')
cap('P44','Um adversário com 20 de vida. Um golpe que tira 8. Dois ataques ainda deixam 4; o terceiro vence a luta.\n\nNa Batalha de Monstrinhos, exemplo do nosso Estúdio, quem cria escolhe os valores e monta a regra do dano. Depois, joga para comparar o resultado com a conta.\n\nMudar a força para 4 aumenta a quantidade de golpes necessários para cinco. A matemática participa de uma decisão: quanto essa batalha deve durar?\n\nÉ uma forma de praticar contas e conferir seus efeitos numa criação que a criança consegue experimentar.\n\nSiga @criecomhelenaejulio para ver outras contas que mudam os jogos.')
note('P44','Preserva o contraste da capa e a conta da batalha. Retira generalizações sobre o ensino escolar e o motivo de toda pergunta infantil; mostra cálculo, programação e teste.')

title('P45','Ele mudou um número. Agora quer descobrir até onde o balão vai.')
art('P45','Ele mudou um número.\n\nAgora quer descobrir até onde o balão vai.')
cap('P45','Mais força faz o balão subir melhor. Mas também pode gastar o combustível mais rápido. Compensa?\n\nNo Balão, exemplo do nosso Estúdio, segurar o mouse acende o fogo. Quem cria escolhe a força e pode comparar o alcance dos voos.\n\nMantendo o restante igual, mudar esse valor abre uma investigação: quanto subiu, quanto combustível gastou e onde conseguiu chegar. O teste oferece informações para escolher o próximo ajuste.\n\nCriar jogos dá espaço a perguntas assim. A criança pode formular uma ideia e construir a experiência para examiná-la.\n\nSiga @criecomhelenaejulio para ver o que acontece quando uma pergunta vira um teste de jogo.')
note('P45','Substitui as vinte tentativas inventadas por uma experiência concreta. Mantém curiosidade e iniciativa sem prometer atenção sustentada nem opor jogar a perguntar.')

slide('P46',1,'Abra um programa que ele nunca viu e repare no primeiro minuto.\n\nPor onde ele tenta começar?')
slide('P46',2,'Pode procurar uma instrução, explorar um botão ou pedir ajuda.\n\nVocês podem escolher um objetivo pequeno para orientar essa primeira tentativa.')
slide('P46',3,'Um caminho para experimentar:\n\nescolher o que fazer;\nlocalizar o comando;\nmudar uma coisa;\nconferir o efeito.\n\nA orientação da ferramenta ajuda a encontrar cada passo.')
slide('P46',5,'Para alcançar uma moeda, ele pode mudar a posição de uma plataforma e testar o salto.\n\nO objetivo ajuda a escolher onde mexer. O teste mostra o efeito da mudança.')
slide('P46',6,'O Estúdio oferece jogos 2D, jogos 3D e mundos para explorar. Outras ferramentas da plataforma permitem desenhar e modelar personagens.\n\nCada criação traz novos comandos para conhecer.')
slide('P46',7,'Aprender uma ferramenta inclui descobrir onde buscar orientação e como testar uma ideia.\n\nSiga @criecomhelenaejulio para acompanhar essas descobertas na criação de jogos.')
cap('P46','Diante de uma ferramenta nova, um objetivo pequeno ajuda a escolher a primeira tentativa.\n\nNo Salto nas Nuvens, do nosso Estúdio, há plataformas e moedas num cenário em 3D. Para mudar o caminho, quem cria localiza uma plataforma, ajusta a posição e testa o salto.\n\nNesse processo, pratica procurar uma orientação, experimentar um comando e conferir o resultado. Se algo não sair como queria, tem uma diferença concreta para investigar.\n\nA plataforma oferece outras possibilidades de criação, como desenhar e modelar personagens. Cada uma abre comandos e escolhas para explorar.\n\nSiga @criecomhelenaejulio para conhecer o caminho entre abrir uma ferramenta e realizar uma ideia.')
note('P46','Mantém a curiosidade sobre começar numa ferramenta. Não promete preparar para qualquer tecnologia nem define a prática como única causa de confiança; trabalha uma experiência orientada.')

reel('P47',[
('Ele gosta de Minecraft. De qual parte?','Ele gosta de Minecraft. Falta saber de qual parte.','Júlio abre com o mundo 3D ao fundo.'),
('Construir. Explorar. Criar personagens.','Peça que mostre o que mais gosta de fazer: construir, explorar ou escolher o personagem. A resposta pode sugerir uma ideia para criar.','Desenho, mapa e personagem em três cortes.'),
('A inspiração pode virar outra criação.','Na nossa ferramenta, dá para montar mundos de blocos, escolher cenários e construir regras. No mundo de neve, por exemplo, o carrinho escorrega.','Mundo de Blocos e Inverno Mágico; mostrar escolha do cenário e teste.'),
('Personagem criado no Molda.','Este personagem de blocos foi criado no Molda, da nossa plataforma. Minecraft serve de inspiração para uma criação própria.','Print real tela-molda@2x.webp com personagem legível.'),
('Siga @criecomhelenaejulio','Siga a gente para descobrir o que dá para inventar com mundos, personagens e regras.','Júlio encerra; @ visível.')])
cap('P47','“Gosto de Minecraft” pode abrir conversas sobre construção, exploração, personagens e muitas outras escolhas. Peça que ele mostre uma parte favorita.\n\nEssa referência pode inspirar uma criação na nossa própria ferramenta. O Estúdio permite construir mundos e regras; o Molda permite criar personagens em 3D, como o boneco de blocos mostrado no vídeo.\n\nNo Inverno Mágico, escolher o cenário de neve também muda o movimento do carrinho, que escorrega. Quem cria pode experimentar o visual e conferir seu efeito na partida.\n\nUma referência conhecida oferece ideias para começar. A construção permite experimentar escolhas próprias.\n\nSiga @criecomhelenaejulio para conhecer mundos e personagens feitos na nossa plataforma.')
note('P47','Preserva Minecraft como interesse de entrada e o print real do Molda. Remove perda da noção da hora como diagnóstico e orientações de jogo que ocupavam o lugar das possibilidades de criação.')

slide('P48',3,'Até a chance de encontrar um cristal foi escolhida: cada bloco novo tem 3 chances em 10 de ser cristal.\n\nQuem cria decide o que vale ponto e com que frequência aparece.')
slide('P48',4,'Na Mina de Cristais, feita no nosso Estúdio, quem cria testa duas situações: cavar uma pedra e cavar um cristal.\n\nO placar deve subir apenas com o cristal. Subiu com a pedra? Vale investigar.')
slide('P48',5,'Um número na tela pode depender de escolhas: o que conta, quanto vale e quando aparece.\n\nConhecer essas escolhas ajuda a entender o que aquele número representa.')
slide('P48',6,'Escolham um placar de jogo e tentem descobrir o que ele conta.\n\nVitórias? Tempo? Itens encontrados? Depois procurem a explicação e comparem com o palpite.')
slide('P48',7,'O número continua na tela. Agora vocês têm uma pergunta sobre ele: “o que entrou nessa conta?”.\n\nSiga @criecomhelenaejulio para descobrir as decisões por trás dos placares.')
cap('P48','O placar executa uma regra. Entender essa regra explica o que o número está contando.\n\nNa Mina de Cristais, do nosso Estúdio, cavar cristal soma 1; cavar pedra não soma. Quem cria monta a condição e testa as duas situações. Se o resultado divergir, tem um comportamento específico para investigar.\n\nOutra escolha está na chance de aparecer cristal: 3 em cada 10 possibilidades de sorteio. O jogo também depende dessa decisão.\n\nNa próxima partida, escolham um número da tela e procurem entender o que entrou na conta.\n\nSiga @criecomhelenaejulio para abrir outros jogos por dentro e conhecer suas regras.')
note('P48','Preserva a capa forte e a descoberta da regra do placar. Não presume ingenuidade da criança nem trata toda divergência como uma única causa. Palpites devem ser comparados com a explicação.')

title('P49','Guarde a primeira versão. Ela mostra o que já mudou.')
art('P49','Guarde a primeira versão.\n\nEla mostra o que já mudou.')
cap('P49','Um print do começo e um vídeo da versão atual dão algo concreto para comparar.\n\nO personagem antes só andava. Agora pula, encontra objetos ou passa para outro lugar. Peça que seu filho escolha uma mudança e conte como a fez.\n\nNo Vale Ensolarado Profissional, exemplo do nosso Estúdio, o pulo também serve para derrotar inimigos. Uma regra conhecida ganha outro uso. Construir esse comportamento pede ligar o contato com o inimigo à reação e testar.\n\nGuardar versões ajuda a enxergar decisões e tentativas que o resultado pronto esconde.\n\nSiga @criecomhelenaejulio para conhecer o caminho que existe entre a primeira regra e as próximas ideias.')
note('P49','Mantém o registro de progresso. Sai a generalização sobre memória e a promessa de que uma conquista prova a próxima; a comparação mostra mudanças concretas para conversar.')

slide('P50',2,'“Joga o meu” convida outra pessoa a experimentar uma criação.\n\nQuem chega pela primeira vez pode perceber algo que passou despercebido durante a montagem.')
slide('P50',3,'Observe onde a pessoa hesita, erra ou pede uma explicação.\n\nPode faltar uma pista, um ajuste no obstáculo ou uma instrução. Quem cria decide o que quer melhorar.')
slide('P50',4,'Na Corrida Infinita 3D, do nosso Estúdio, as caixas ficam mais rápidas com o tempo.\n\nSe quem testa achar a aceleração brusca, dá para comparar outro valor.')
slide('P50',5,'Quem cria muda a aceleração e pede outro teste.\n\nA conversa ganha uma pergunta concreta: ficou mais próximo do desafio que queria construir?')
slide('P50',7,'Peça a quem testar que conte uma coisa que gostou e uma parte em que teve dificuldade.\n\nSiga @criecomhelenaejulio para conhecer o que os testes acrescentam à criação de um jogo.')
cap('P50','“No fim eu peguei o link e mandei pro meu amigo jogar.” Rafael, aluno.\n\nMostrar a criação também abre espaço para ouvir. Quem joga pela primeira vez pode se perder num caminho ou encontrar uma dificuldade que o autor não percebeu.\n\nNa Corrida Infinita 3D, exemplo do nosso Estúdio, as caixas aceleram com o tempo. Um comentário sobre a velocidade pode virar uma comparação entre duas versões. Quem cria avalia qual atende melhor à ideia do jogo.\n\nNa nossa plataforma, o projeto pode ser compartilhado por link e no Mural dos Criadores. Combinem para quem enviar e peçam um comentário sobre a experiência.\n\nSiga @criecomhelenaejulio para descobrir como ouvir quem joga ajuda a continuar uma criação.')
note('P50','Preserva o relato e a troca com outra pessoa. Remove cenas inventadas com resultados numéricos e certezas sobre o autor não enxergar problemas; feedback vira informação para decidir.')
